1	import { expect, test, type Locator, type Page } from "@playwright/test";
2	import { createClient } from "@supabase/supabase-js";
3	import { randomBytes, randomUUID } from "node:crypto";
4	import postgres from "postgres";
5	import { deleteDisposableUser } from "./fixtures";
6	
7	test.skip(!process.env.SUPABASE_DB_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY || !process.env.NEXT_PUBLIC_SUPABASE_URL, "Requires disposable Supabase auth and database fixtures");
8	
9	async function drag(page: Page, from: Locator, to: { x: number; y: number }) {
10	  await from.scrollIntoViewIfNeeded();
11	  const start = (await from.boundingBox())!;
12	  await page.mouse.move(start.x + start.width / 2, start.y + start.height / 2);
13	  await page.mouse.down();
14	  await page.mouse.move(start.x + start.width / 2 + 10, start.y + start.height / 2 + 10, { steps: 4 });
15	  await page.mouse.move(to.x, to.y, { steps: 25 });
16	  await page.waitForTimeout(400);
17	  await page.mouse.up();
18	  await page.waitForTimeout(400);
19	}
20	
21	test("a widget dropped in the empty space of a row goes there and stays after a reload", async ({ page }) => {
22	  test.setTimeout(120_000);
23	  await page.setViewportSize({ width: 1440, height: 1300 });
24	  const db = postgres(process.env.SUPABASE_DB_URL!, { max: 1, onnotice: () => {} });
25	  const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false, autoRefreshToken: false } });
26	  const email = `qa-drag-${randomUUID()}@example.invalid`, password = randomBytes(24).toString("hex");
27	  const created = await admin.auth.admin.createUser({ email, password, email_confirm: true, user_metadata: { qa_test: "home-drag" } });
28	  expect(created.error).toBeNull();
29	  const user = created.data.user!.id;
30	  try {
31	    const [{ id: workspace }] = await db`select id from public.workspaces where owner_id=${user}`;
32	    await db`insert into public.dashboard_layouts(workspace_id,items,sizes) values(${workspace},${["recent", "accounts", "goals"]},${db.json({ recent: "L", accounts: "L", goals: "S" })})`;
33	    await page.goto("/login");
34	    await page.getByLabel("Email").fill(email);
35	    await page.getByLabel("Password").fill(password);
36	    await page.getByRole("button", { name: "Sign in", exact: true }).click();
37	    await page.waitForURL(url => url.pathname === "/");
38	    const widget = (name: string) => page.locator(`[data-widget="${name}"]`);
39	    await expect(widget("goals")).toBeVisible();
40	    const box = async (name: string) => (await widget(name).boundingBox())!;
41	
42	    // Goals starts beside the second wide widget, with two free columns in the row above.
43	    expect(Math.abs((await box("goals")).y - (await box("accounts")).y)).toBeLessThan(2);
44	    const first = await box("recent"), grid = (await page.locator("[data-widget]").first().locator("..").boundingBox())!;
45	    await widget("goals").hover();
46	    await drag(page, page.getByRole("button", { name: /^Move Goals/ }), { x: grid.x + grid.width - 40, y: first.y + 60 });
47	    await expect.poll(async () => Math.abs((await box("goals")).y - (await box("recent")).y)).toBeLessThan(2);
48	    expect((await box("goals")).x).toBeGreaterThan((await box("recent")).x);
49	
50	    await expect.poll(async () => (await db`select items from public.dashboard_layouts where workspace_id=${workspace}`)[0].items).toEqual(["recent", "goals", "accounts"]);
51	    await page.reload();
52	    await expect(widget("goals")).toBeVisible();
53	    expect(Math.abs((await box("goals")).y - (await box("recent")).y)).toBeLessThan(2);
54	
55	    // Below the last widget still counts as a place to drop.
56	    await widget("recent").hover();
57	    const last = await box("accounts");
58	    await drag(page, page.getByRole("button", { name: /^Move Recent/ }), { x: last.x + 20, y: last.y + last.height + 200 });
59	    await expect.poll(async () => (await db`select items from public.dashboard_layouts where workspace_id=${workspace}`)[0].items).toEqual(["goals", "accounts", "recent"]);
60	  } finally {
61	    await deleteDisposableUser(db, user);
62	    await db.end();
63	  }
64	});
