// Temporary diagnosis; never committed.
import { expect, test } from "@playwright/test";
import { createClient } from "@supabase/supabase-js";
import { randomBytes, randomUUID } from "node:crypto";
import { readFileSync, existsSync } from "node:fs";
import postgres from "postgres";
import { deleteDisposableUser } from "./fixtures";

test("drag boxes", async ({ page }, info) => {
  test.setTimeout(120_000);
  await page.setViewportSize({ width: 1440, height: 1300 });
  const db = postgres(process.env.SUPABASE_DB_URL!, { max: 1, onnotice: () => {} });
  const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false, autoRefreshToken: false } });
  const email = `qa-drag-${randomUUID()}@example.invalid`, password = randomBytes(24).toString("hex");
  const created = await admin.auth.admin.createUser({ email, password, email_confirm: true, user_metadata: { qa_test: "home-drag" } });
  const user = created.data.user!.id;
  try {
    const [{ id: workspace }] = await db`select id from public.workspaces where owner_id=${user}`;
    await db`insert into public.dashboard_layouts(workspace_id,items,sizes) values(${workspace},${["recent", "accounts", "goals"]},${db.json({ recent: "L", accounts: "L", goals: "S" })})`;
    await page.goto("/login");
    await page.getByLabel("Email").fill(email);
    await page.getByLabel("Password").fill(password);
    await page.getByRole("button", { name: "Sign in", exact: true }).click();
    await page.waitForURL(url => url.pathname === "/");
    await expect(page.locator('[data-widget="goals"]')).toBeVisible();
    const dump = (label: string) => page.evaluate(label => {
      const grid = document.querySelector("[data-widget]")!.parentElement!;
      return { label, cols: getComputedStyle(grid).gridTemplateColumns, children: [...grid.children].map(node => { const r = node.getBoundingClientRect(), e = node as HTMLElement; return { w: e.dataset.widget ?? node.tagName, cls: e.className.slice(0, 60), x: Math.round(r.x), y: Math.round(r.y), width: Math.round(r.width), height: Math.round(r.height), start: getComputedStyle(node).gridColumnStart, end: getComputedStyle(node).gridColumnEnd, display: getComputedStyle(node).display }; }) };
    }, label);
    console.log(JSON.stringify(await dump("before")));
    const first = (await page.locator('[data-widget="recent"]').boundingBox())!, grid = (await page.locator("[data-widget]").first().locator("..").boundingBox())!;
    await page.locator('[data-widget="goals"]').hover();
    const grip = page.getByRole("button", { name: /^Move Goals/ });
    await grip.scrollIntoViewIfNeeded();
    const start = (await grip.boundingBox())!;
    await page.mouse.move(start.x + start.width / 2, start.y + start.height / 2);
    await page.mouse.down();
    await page.mouse.move(start.x + start.width / 2 + 10, start.y + start.height / 2 + 10, { steps: 4 });
    await page.mouse.move(grid.x + grid.width - 40, first.y + 60, { steps: 25 });
    await page.waitForTimeout(400);
    console.log(JSON.stringify(await dump("held")));
    await page.mouse.up();
    await page.waitForTimeout(1500);
    console.log(JSON.stringify(await dump("after")));
    await page.screenshot({ path: info.outputPath("after.png") });
  } finally { await deleteDisposableUser(db, user); await db.end(); }
});

const state = process.env.E2E_STORAGE_STATE ?? (existsSync("e2e/.auth.json") ? "e2e/.auth.json" : undefined);
test("phone swipe", async ({ browser }) => {
  readFileSync(state!);
  const context = await browser.newContext({ storageState: state!, viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
  const page = await context.newPage();
  await page.goto("/", { waitUntil: "networkidle" });
  const cdp = await context.newCDPSession(page);
  const touch = async (type: "touchStart" | "touchMove" | "touchEnd", x = 0, y = 0) => { await cdp.send("Input.dispatchTouchEvent", { type, touchPoints: type === "touchEnd" ? [] : [{ x, y }] }); await page.waitForTimeout(20); };
  const swipe = async (label: string, stepPx: number, steps: number) => {
    await page.evaluate(() => scrollTo(0, 0));
    await page.waitForTimeout(200);
    const from = (await page.locator("[data-widget]:visible").first().boundingBox())!;
    const info = await page.evaluate(([x, y]) => { const e = document.elementFromPoint(x, y)!; return { scrollHeight: document.scrollingElement!.scrollHeight, inner: innerHeight, top: scrollY, at: e.tagName, cls: String(e.className).slice(0, 80), touchAction: getComputedStyle(e).touchAction, overflow: getComputedStyle(document.body).overflow, htmlOverflow: getComputedStyle(document.documentElement).overflow }; }, [from.x + 40, from.y + 30]);
    await touch("touchStart", from.x + 40, from.y + 30);
    for (let step = 1; step <= steps; step++) await touch("touchMove", from.x + 40, from.y + 30 - step * stepPx);
    await touch("touchEnd");
    await page.waitForTimeout(1500);
    console.log(label, JSON.stringify({ from: { x: from.x, y: from.y }, ...info, after: await page.evaluate(() => scrollY) }));
  };
  await swipe("not customizing 6x20", 20, 6);
  await swipe("not customizing 12x20", 20, 12);
  await page.getByRole("button", { name: "Customize", exact: true }).click();
  await swipe("customizing 6x20", 20, 6);
  await swipe("customizing 12x20", 20, 12);
  await context.close();
});

