// Read-only: round-trip latency, connection counts by application, and long-running or waiting queries. Prints no query text or user data.
import { createRequire } from "node:module";
import { pathToFileURL } from "node:url";
const require = createRequire(`${process.cwd()}/`);
process.loadEnvFile(".env");
const { default: postgres } = await import(pathToFileURL(require.resolve("postgres")).href);
const db = postgres(process.env.SUPABASE_DB_URL, { ssl: "require", max: 1 });
const times = [];
for (let i = 0; i < 8; i++) { const start = performance.now(); await db`select 1`; times.push(Math.round(performance.now() - start)); }
console.log("round trips ms", times.join(" "));
console.log("connections", (await db`select coalesce(application_name,'') app, state, count(*)::int n from pg_stat_activity where datname=current_database() group by 1,2 order by 3 desc limit 12`).map(r => `${r.n} ${r.state ?? "-"} ${r.app.slice(0, 40)}`));
console.log("limit", (await db`select setting from pg_settings where name='max_connections'`)[0].setting);
console.log("long or waiting", (await db`select pid, state, wait_event_type, wait_event, round(extract(epoch from clock_timestamp()-query_start))::int secs, left(application_name,30) app from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() and state<>'idle' order by query_start limit 10`));
console.log("sizes", (await db`select pg_size_pretty(pg_database_size(current_database())) db`)[0].db, (await db`select count(*)::int users from auth.users`)[0].users, "users");
await db.end();

