// Compares each browser test's duration and outcome across all required runs, flagging slow windows.
import { existsSync, readFileSync, readdirSync } from "node:fs";
const runs = readdirSync(".qa").filter(name => /^acceptance-required-\d+$/.test(name)).sort().filter(name => existsSync(`.qa/${name}/browser.json`));
const table = new Map();
runs.forEach((run, index) => {
  const walk = suite => {
    for (const child of suite.suites ?? []) walk(child);
    for (const spec of suite.specs ?? []) for (const test of spec.tests) for (const result of test.results) {
      const key = `${spec.file} :: ${spec.title.slice(0, 44)}`;
      if (!table.has(key)) table.set(key, []);
      table.get(key)[index] = { d: Math.round(result.duration / 1000), s: result.status, at: result.startTime.slice(11, 19) };
    }
  };
  JSON.parse(readFileSync(`.qa/${run}/browser.json`, "utf8")).suites.forEach(walk);
});
console.log(runs.join(" | "));
const median = values => [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)];
for (const [key, cells] of table) {
  const passed = cells.filter(cell => cell?.s === "passed").map(cell => cell.d), base = median(passed.length ? passed : [1]);
  const interesting = cells.some(cell => cell && (cell.s !== "passed" || cell.d >= Math.max(base * 2, base + 8)));
  if (interesting) console.log(key, "\n   ", cells.map(cell => cell ? `${cell.at} ${cell.d}s ${cell.s === "passed" ? "ok" : "FAIL"}` : "-").join(" | "));
}
console.log("tests", table.size, "never passed in a full run:", [...table].filter(([, cells]) => !cells.some(cell => cell?.s === "passed")).map(([key]) => key));

